library(ggplot2);library(dplyr);library(tidyr);library(patchwork)
args<-commandArgs(FALSE);self<-sub('--file=','',args[grepl('^--file=',args)])[1];setwd(dirname(normalizePath(self)))
read_panel<-function(letter,name)read.csv(paste0('Supplementary_Fig19_Panel',letter,'_',name,'.csv'))
th<-theme_classic(base_size=7,base_family='sans')+theme(axis.title=element_text(size=7,face='bold'),axis.text=element_text(size=6,colour='black'),strip.text=element_text(size=7,face='bold'),legend.position='bottom',legend.title=element_blank(),legend.text=element_text(size=6),plot.title=element_text(size=8,face='bold'),plot.tag=element_text(size=8,face='bold'),plot.margin=margin(5,6,5,5))
rulecols<-c(C='#BC7B61',F='#367D99')
a<-read_panel('A','Central_Annual')%>%transmute(Year,Rule,`GHG (Mt CO2e)`=Total_GHG_tCO2e/1e6,`Catch (Mt)`=Realised_Fleet_Catch_Mt)%>%pivot_longer(-c(Year,Rule),names_to='Metric',values_to='Value')
pa<-ggplot(a,aes(Year,Value,colour=Rule))+geom_line(linewidth=.55)+facet_wrap(~Metric,scales='free_y')+scale_colour_manual(values=rulecols,labels=c(C='Fixed-quota rule',F='Adjusted harvest-rate rule'))+labs(x='Year',y=NULL,title='The matched totals conceal different annual paths (F41)')+th
b<-read_panel('B','Matched_Pairs')
pb<-ggplot(b,aes(Future,GHG_C_Mt))+geom_segment(aes(xend=Future,yend=GHG_F_Mt),colour='grey70',linewidth=.5)+geom_point(colour=rulecols['C'],size=1.7)+geom_point(aes(y=GHG_F_Mt),colour=rulecols['F'],size=1.7)+coord_flip()+labs(x=NULL,y=expression('2025-2050 GHG (Mt CO'[2]*'e)'),title='The benefit occurs in all nine comparisons')+th
c<-read_panel('C','Decomposition')%>%filter(!Term%in%c('Structural-zero cells','LL/PS materials, gear and leakage'))%>%mutate(Saving=-Delta_Mt,Term=factor(Term,levels=c('Cumulative catch scale','Species composition','Within-species catch timing','Effort per catch','GHG per effort','Support vessels')))
pc<-ggplot(c,aes(Term,Saving))+geom_hline(yintercept=0,colour='grey65',linewidth=.3)+geom_boxplot(width=.5,outlier.shape=NA,fill='#B4D1D9',linewidth=.3)+geom_point(position=position_jitter(width=.09,seed=1),size=.8,alpha=.65,colour='#367D99')+coord_flip()+scale_x_discrete(labels=c('Within-species catch timing'='Catch timing within species','Cumulative catch scale'='Total catch scale'))+labs(x=NULL,y=expression('Contribution to GHG saving (Mt CO'[2]*'e)'),title='Contributions to GHG savings')+th
d<-read_panel('D','Standardisation')%>%select(Future,Reduction_pct,Variable_GHG_reduction_pct,Species_standardised_intensity_reduction_pct,Species_year_standardised_intensity_reduction_pct)%>%pivot_longer(-Future,names_to='Comparison',values_to='Reduction')%>%mutate(Comparison=factor(Comparison,levels=c('Reduction_pct','Variable_GHG_reduction_pct','Species_standardised_intensity_reduction_pct','Species_year_standardised_intensity_reduction_pct')))
pd<-ggplot(d,aes(Comparison,Reduction))+geom_boxplot(width=.5,outlier.shape=NA,fill='#B4D1D9',linewidth=.3)+geom_point(position=position_jitter(width=.08,seed=1),size=.8,colour='#367D99')+scale_x_discrete(labels=c('Whole fleet\nGHG','LL/PS variable\nGHG','Common species\nweights','Common species-\nyear weights'))+labs(x=NULL,y='Reduction (%)',title='A residual activity-intensity difference remains')+th
e<-read_panel('E','Stock_Effort')%>%filter(Stock%in%c('BET','YFT','SBT'))%>%select(Year,Stock,Rule,B_Start_Mt,Effort_per_t)%>%pivot_longer(c(B_Start_Mt,Effort_per_t),names_to='Metric',values_to='Value')%>%group_by(Stock,Metric)%>%mutate(Value=Value/Value[Year==2025&Rule=='C'])%>%ungroup()
pe<-ggplot(e,aes(Year,Value,colour=Rule))+geom_line(linewidth=.45)+facet_grid(Metric~Stock,scales='free_y',labeller=labeller(Metric=c(B_Start_Mt='Biomass index',Effort_per_t='Effort / catch')))+scale_colour_manual(values=rulecols,guide='none')+labs(x='Year',y='Index (C rule, 2025 = 1)',title='Biomass and effort per catch follow different rule trajectories (F41)')+th
fig<-pa/(pb|pc)/pd/pe+plot_layout(heights=c(.9,1.2,.8,1.15))+plot_annotation(tag_levels='a',tag_prefix='(',tag_suffix=')')
for(letter in c('A','B','C','D','E')){f<-list.files(pattern=paste0('Panel',letter,'_.*csv$'));z<-read.csv(f);write.csv(z,f,row.names=FALSE)}
ggsave('Supplementary_Fig19_Validation.pdf',fig,width=183,height=220,units='mm',device=cairo_pdf,bg='white')
ggsave('Supplementary_Fig19_Validation.png',fig,width=183,height=220,units='mm',dpi=300,bg='white')
ggsave('Supplementary_Fig19_Validation.tiff',fig,width=183,height=220,units='mm',dpi=900,compression='lzw',bg='white')
